// Golden SCOs generated by these exact fixtures at integration 309ad4d.
// The three normal plates intentionally have new path records. Their mesh name
// includes a hash of the full SCO body, so mask only those two derived identifiers.
// Keep all other bytes (including straight, pedestrian and helper records) exact;
// the two unchanged bus-bay snapshots still compare their original full bytes.
fn junction_snapshot_bytes(name: &str, bytes: &[u8]) -> Vec<u8> {
    if name.starts_with("pocket-") { return bytes.to_vec(); }
    let text = std::str::from_utf8(bytes).unwrap();
    let friendly = text.split_once("[friendlyname]\r\nJunction ").unwrap().1.split_once("\r\n").unwrap().0;
    let mesh = text.split_once("[mesh]\r\njunction_").unwrap().1.split_once(".x\r\n").unwrap().0;
    assert_eq!(friendly.len(), 6);
    assert_eq!(mesh.len(), 16);
    assert!(mesh.starts_with(friendly) && mesh.bytes().all(|b| b.is_ascii_hexdigit()));
    text.replacen(&format!("[friendlyname]\r\nJunction {friendly}\r\n"), "[friendlyname]\r\nJunction 000000\r\n", 1)
        .replacen(&format!("[mesh]\r\njunction_{mesh}.x\r\n"), "[mesh]\r\njunction_0000000000000000.x\r\n", 1)
        .into_bytes()
}

fn compare_junction_snapshot(name: &str, bytes: &[u8]) {
    let root = std::env::var_os("OPENMAPPER_SNAPSHOT_WRITE")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/junction-baseline"));
    let file = root.join(format!("{name}.sco"));
    if std::env::var_os("OPENMAPPER_SNAPSHOT_WRITE").is_some() {
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(file, junction_snapshot_bytes(name, bytes)).unwrap();
    } else {
        assert_eq!(junction_snapshot_bytes(name, bytes), std::fs::read(&file).unwrap(), "snapshot {}", file.display());
    }
}

#[test]
fn junction_sco_baseline_snapshots() {
    for (name, headings, zebra) in [
        ("three-arm", vec![0.0, 90.0, 270.0], false),
        ("four-arm", vec![0.0, 90.0, 180.0, 270.0], false),
        ("zebra", vec![0.0, 90.0, 180.0, 270.0], true),
    ] {
        let (mut assets, dir, plain, _) = pocket_fixture(name);
        let content = dir.join("content");
        let mut doc = flat_map(1);
        doc.dir = content.join("maps").join("Snapshot");
        let centre = DVec3::new(150.0, 150.0, 0.0);
        let mut arms = Vec::new();
        for (i, heading) in headings.iter().enumerate() {
            let p = centre.truncate() + crate::roads::dir(*heading) * 18.0;
            let id = i as i64 + 1;
            doc.tiles.get_mut(&(0, 0)).unwrap().tile.splines.push(MapSpline {
                file: plain.clone(), id, pos: [p.x, p.y, 0.0], heading: *heading,
                length: 50.0, ..Default::default()
            });
            arms.push(crate::junction::Arm { key: (0, 0), id, at_end: false });
        }
        let opts = crate::junction::Options { crossings: if zebra { vec![0.0, 90.0] } else { vec![] }, ..Default::default() };
        let id = crate::junction::make_with(&mut doc, &mut assets, &content, None, centre, &arms, &opts, Default::default()).unwrap();
        let obj = doc.tiles[&(0, 0)].tile.objects.iter().find(|o| o.id == id).unwrap();
        assert!(obj.rules.is_empty());
        compare_junction_snapshot(name, &std::fs::read(omsi_cfg::resolve_path(&content, &obj.file)).unwrap());
        std::fs::remove_dir_all(dir).unwrap();
    }
    for both in [false, true] {
        let name = if both { "pocket-both" } else { "pocket-one" };
        let (mut assets, dir, plain, _) = pocket_fixture(name);
        let content = dir.join("content");
        let mut doc = flat_map(1);
        doc.dir = content.join("maps").join("Snapshot");
        doc.tiles.get_mut(&(0, 0)).unwrap().tile.splines.push(MapSpline {
            file: plain, id: 1, pos: [150.0, 60.0, 0.0], length: 180.0, ..Default::default()
        });
        let mut ed = Editor::default();
        ed.content_dir = Some(content.clone());
        ed.open(doc);
        ed.set_tool(Tool::Roads);
        ed.bus_pocket = true;
        ed.pocket_both_sides = both;
        ed.cursor = Some(DVec3::new(150.0, 150.0, 0.0));
        ed.left_press(&mut assets, &Library::default(), false);
        let tile = &ed.doc.as_ref().unwrap().tiles[&(0, 0)].tile;
        let mut plates: Vec<_> = tile.objects.iter().filter(|o| is_bus_bay_junction(&o.file)).collect();
        plates.sort_by(|a, b| a.pos[1].total_cmp(&b.pos[1]));
        assert_eq!(plates.len(), 2);
        compare_junction_snapshot(name, &std::fs::read(omsi_cfg::resolve_path(&content, &plates[0].file)).unwrap());
        std::fs::remove_dir_all(dir).unwrap();
    }
}
